const data = window.EXAM_DATA;
const groups = data.labels.map(([from, to, name]) => ({ from, to, name, questions: data.questions.filter(q => q.no >= from && q.no <= to) }));
const key = 'tfs4-2025-prototype-session';
const archiveKey = 'tfs4-2025-prototype-archive';
let session = JSON.parse(localStorage.getItem(key) || 'null') || { answers: {}, questionTimes: {}, startedAt: Date.now(), activeSeconds: 0, lastTick: Date.now(), started: false };
session.questionTimes ||= {}; session.activeQuestionNo ||= null; session.activeQuestionStartedAt ||= null;
let page = Number.isInteger(session.page)&&session.page>=0&&session.page<groups.length?session.page:0;
let questionObserver;
const $ = s => document.querySelector(s);
const duration = () => session.activeSeconds + (session.started ? Math.floor((Date.now() - session.lastTick) / 1000) : 0);
const fmt = n => [Math.floor(n/3600),Math.floor(n%3600/60),n%60].map(x=>String(x).padStart(2,'0')).join(':');
const save = () => localStorage.setItem(key, JSON.stringify({...session, activeSeconds: duration(), lastTick: Date.now()}));
function recordQuestionTime(){if(!session.started||!session.activeQuestionNo||session.activeQuestionStartedAt===null)return;const now=duration(),delta=Math.max(0,now-session.activeQuestionStartedAt);session.questionTimes[session.activeQuestionNo]=(session.questionTimes[session.activeQuestionNo]||0)+delta;session.activeQuestionStartedAt=now;}
function focusQuestion(no){if(String(no)===String(session.activeQuestionNo))return;recordQuestionTime();session.activeQuestionNo=String(no);session.activeQuestionStartedAt=duration();}
function render() {
  const group = groups[page]; session.page=page;
  const listening=group.to<=20; $('#listening-player').hidden=!listening; if(!listening)$('#listening-audio').pause(); $('#group-name').textContent = group.name; $('#page-title').textContent = `第 ${group.from}–${group.to} 题`;
  const answered = Object.values(session.answers).filter(a => a.choice).length; $('#answered-count').textContent = answered;
  $('#page-dots').innerHTML = groups.map((g,i) => `<button class="${i===page?'active':''} ${g.questions.every(q=>session.answers[q.no]?.choice)?'done':''}" data-page="${i}" aria-label="第 ${g.from} 到 ${g.to} 题">${i+1}</button>`).join('');
  const context = data.contexts[String(group.from)];
  $('#questions').innerHTML = `${context ? `<article class="reading">${formatPassage(context)}</article>` : ''}` + group.questions.map(q => `<article class="question" data-no="${q.no}"><div class="q-top"><span class="q-no">${q.no}</span><span class="q-group">${q.group}</span></div><h3>${escapeHTML(q.text)}</h3><div class="option-list">${Object.keys(q.options).map(letter => `<button class="option ${session.answers[q.no]?.choice===letter?'selected':''}" data-choice="${letter}"><b>${letter}</b><span>${escapeHTML(q.options[letter])}</span></button>`).join('')}</div><div class="confidence"><span>这题把握：</span>${[['肯定','🟢'],['犹豫','🟡'],['猜测','🔴']].map(([v,icon])=>`<button data-confidence="${v}" class="${session.answers[q.no]?.confidence===v?'selected':''}">${icon} ${v}</button>`).join('')}</div></article>`).join('');
  $('#prev').disabled = page === 0; $('#next').textContent = page === groups.length-1 ? '返回第一组 ↺' : '下一组 →';
  $('#page-dots').querySelectorAll('button').forEach(b => b.onclick=()=>{page=Number(b.dataset.page);render();window.scrollTo({top:0,behavior:'smooth'})});
  $('#questions').querySelectorAll('button').forEach(b=>b.onclick=()=>answer(b));
  questionObserver?.disconnect();
  questionObserver = new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio);if(visible[0])focusQuestion(visible[0].target.dataset.no);},{threshold:.55});
  $('#questions').querySelectorAll('[data-no]').forEach(card=>questionObserver.observe(card));
  focusQuestion(group.from);
}
function escapeHTML(v=''){return v.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function formatPassage(text){const parts=text.split(/\n{2,}/).map(x=>x.trim()).filter(Boolean);const [title,...body]=parts;return `<div class="reading-copy"><h3>${escapeHTML(title||'Texte')}</h3>${body.map(p=>`<p>${escapeHTML(p).replace(/\n/g,' ')}</p>`).join('')}</div>`;}
function answer(btn){const card=btn.closest('[data-no]'), no=card.dataset.no;focusQuestion(no);const old=session.answers[no]||{};session.answers[no]={...old,firstAnsweredAt:old.firstAnsweredAt??duration(),lastChangedAt:duration()};if(btn.dataset.choice)session.answers[no].choice=btn.dataset.choice;if(btn.dataset.confidence)session.answers[no].confidence=btn.dataset.confidence;save();render();}
function pauseSession(){recordQuestionTime();session.activeSeconds=duration();session.lastTick=Date.now();session.started=false;session.activeQuestionStartedAt=null;$('#listening-audio').pause();$('#clock').textContent=fmt(session.activeSeconds);save();}
function start(){session.started=true;session.activeQuestionStartedAt=session.activeSeconds;session.lastTick=Date.now();$('#welcome').hidden=true;$('#history').hidden=true;$('#archive-detail').hidden=true;$('#exam').hidden=false;render();save();}
function fmtShort(n){return n==null?'—':n<60?`${n} 秒`:`${Math.floor(n/60)} 分 ${n%60} 秒`;}
function confidenceBadge(level){return ({'肯定':'🟢 肯定','犹豫':'🟡 犹豫','猜测':'🔴 猜测'})[level]||'—';}
function reportAnswer(q,record){return record?.answerKey?.[q.no]||(record?.answerKeyVersion?q.answer:({61:'D',62:'D'}[q.no]||q.answer));}
function isCorrect(q,answer,record){return !!answer?.choice && answer.choice===reportAnswer(q,record);}
function showHistory(){pauseSession();$('#welcome').hidden=true;$('#exam').hidden=true;$('#archive-detail').hidden=true;$('#history').hidden=false;const rows=JSON.parse(localStorage.getItem(archiveKey)||'[]');$('#history-list').innerHTML=rows.length?rows.map((r,i)=>`<button class="history-card" data-record="${i}"><div><b>${new Date(r.submittedAt).toLocaleString('zh-CN',{hour12:false})}</b><p>用时 ${fmt(r.duration)} · 已答 ${r.answered}/100 · 肯定 ${r.confidence?.肯定||0}</p></div><strong>${r.score}<small> / 100</small></strong></button>`).join(''):'<p class="empty">还没有已交卷的考试记录。</p>';$('#history-list').querySelectorAll('[data-record]').forEach(btn=>btn.onclick=()=>showRecord(rows[Number(btn.dataset.record)]));}
function showRecord(record){$('#history').hidden=true;$('#archive-detail').hidden=false;const answered=Object.values(record.answers||{}).filter(a=>a.choice).length;const accuracy=answered?Math.round(record.score/answered*100):0;const parts=groups.map(group=>{const answeredInPart=group.questions.filter(q=>record.answers?.[q.no]?.choice);const correct=answeredInPart.filter(q=>isCorrect(q,record.answers[q.no],record)).length;const percent=answeredInPart.length?Math.round(correct/answeredInPart.length*100):0;const rows=group.questions.map(q=>{const answer=record.answers?.[q.no],status=!answer?.choice?'empty':isCorrect(q,answer,record)?'correct':'wrong';const mark=status==='correct'?'✓':status==='wrong'?'×':'–';return `<div class="result-row ${status}"><span class="mark">${mark}</span><span>第 ${q.no} 题${status==='wrong' ? ` · 正确答案 ${reportAnswer(q,record)}` : ''}</span><span class="answer">${answer?.choice||'未作答'}</span><span class="report-confidence">${confidenceBadge(answer?.confidence)}</span><span class="time">${fmtShort(record.questionTimes?.[q.no])}</span></div>`;}).join('');return `<details class="part-report" open><summary><div><strong>${group.name}</strong><span> · 第 ${group.from}–${group.to} 题</span></div><b>${correct}/${answeredInPart.length||0} · ${percent}%</b></summary><div class="part-questions">${rows}</div></details>`;}).join('');$('#archive-content').innerHTML=`<div class="archive-overview"><div class="archive-metric"><b>${record.score}/100</b>总分</div><div class="archive-metric"><b>${accuracy}%</b>已答题正确率</div><div class="archive-metric"><b>${fmt(record.duration)}</b>总用时</div></div>${parts}`;}
function submit(){recordQuestionTime();const answered=Object.values(session.answers).filter(a=>a.choice).length;if(!confirm(`已作答 ${answered}/100 题。提交后，本次记录会保存到本机。确定交卷吗？`))return;const choices=Object.entries(session.answers);const score=choices.filter(([no,a])=>a.choice===data.questions.find(q=>q.no===Number(no))?.answer).length;const confidence=Object.values(session.answers).reduce((o,a)=>(a.confidence&&(o[a.confidence]=(o[a.confidence]||0)+1),o),{});$('#listening-audio').pause();const record={answerKeyVersion:'2025-reference-v1',answerKey:Object.fromEntries(data.questions.map(q=>[q.no,q.answer])),submittedAt:Date.now(),duration:duration(),answered,score,confidence,answers:session.answers,questionTimes:session.questionTimes};const rows=JSON.parse(localStorage.getItem(archiveKey)||'[]');rows.unshift(record);localStorage.setItem(archiveKey,JSON.stringify(rows));$('#result-content').innerHTML=`<p class="kicker">本次选择题成绩</p><div class="score">${score}<small> / 100</small></div><p class="result-copy">本次答题与用时已保存到本机。本次按用户确认的官方参考答案评分。</p><div class="result-grid"><div><b>${fmt(record.duration)}</b>总用时</div><div><b>${answered}</b>已作答</div><div><b>${confidence.肯定||0}</b>肯定</div></div>`;$('#result').showModal();session={answers:{},questionTimes:{},startedAt:Date.now(),activeSeconds:0,lastTick:Date.now(),started:false,activeQuestionNo:null,activeQuestionStartedAt:null};localStorage.removeItem(key);page=0;$('#listening-audio').currentTime=0;}
$('#start').onclick=start;$('#open-history').onclick=showHistory;document.querySelector('.back').onclick=()=>{ $('#history').hidden=true; session.started=false; $('#welcome').hidden=false;};$('#archive-back').onclick=showHistory;$('#prev').onclick=()=>{if(page>0){page--;render();window.scrollTo({top:0,behavior:'smooth'})}};$('#next').onclick=()=>{page=page===groups.length-1?0:page+1;render();window.scrollTo({top:0,behavior:'smooth'})};$('#submit').onclick=submit;$('#result-close').onclick=()=>{$('#result').close();$('#exam').hidden=true;$('#welcome').hidden=false;};setInterval(()=>{if(session.started)recordQuestionTime();$('#clock').textContent=fmt(duration());if(session.started)save()},1000);$('#clock').textContent=fmt(duration());if(session.started){session.started=false;session.lastTick=Date.now();session.activeQuestionStartedAt=null;save();$('#start').innerHTML='继续本次考试 <span>→</span>';}

$('#pause-exam').onclick=()=>{pauseSession();$('#exam').hidden=true;$('#welcome').hidden=false;$('#start').innerHTML='继续本次考试 <span>→</span>';};
$('#listening-audio').addEventListener('error',()=>{$('#audio-status').textContent='音频暂不可用，请检查本机音频配置。';});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&session.started)$('#pause-exam').click();});
window.addEventListener('pagehide',()=>{if(session.started)pauseSession();});
